import {MODES,MOVES,mode,init,active,midpoint,expectedMove,applyMove,result,qualifies,guardFeedback,validateInput,generateCases,python} from './engine.js';

const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='bisect.learning.v1';
let id='exact_closed',caseIndex=0,caseName='',s,history=[],guard=false,completed=false,feedback=null,pending=null,tab='reason',custom=false,menu=false,resetOpen=false,storageAvailable=true,codeFeedback=null,blankValues={};
let progress={completed:[],code:[]};
function caseKey(){return `${id}:${JSON.stringify(s.a)}:${s.target}`}
function start(nextId=id,index=0,customCase){id=nextId;caseIndex=index;const c=customCase??generateCases(id)[index];caseName=c.name;s=init(id,c.a,c.target);history=[];guard=false;completed=false;feedback=null;pending=null;codeFeedback=null;blankValues={};custom=false;save();render()}
function save(){try{localStorage.setItem(KEY,JSON.stringify({version:1,id,caseIndex,caseName,a:s.a,target:s.target,moves:history.map(h=>h.move),guard,completed,progress}));storageAvailable=true}catch{storageAvailable=false}}
function restore(){try{const r=JSON.parse(localStorage.getItem(KEY));if(!r||r.version!==1||validateInput(r.id,r.a,r.target))return false;id=r.id;caseIndex=Number.isInteger(r.caseIndex)&&r.caseIndex>=0&&r.caseIndex<generateCases(id).length?r.caseIndex:0;caseName=typeof r.caseName==='string'?r.caseName.slice(0,80):'Custom case';const preset=generateCases(id)[caseIndex];if(JSON.stringify(preset.a)!==JSON.stringify(r.a)||preset.target!==r.target)caseName='Custom case';s=init(id,r.a,r.target);history=[];for(const move of Array.isArray(r.moves)?r.moves.slice(0,64):[]){const a=applyMove(s,move);if(!a.ok)break;history.push({before:s,move,explanation:a.reason});s=a.state}guard=r.guard===true;completed=r.completed===true&&!active(s);if(r.progress&&Array.isArray(r.progress.completed)&&Array.isArray(r.progress.code))progress={completed:r.progress.completed.filter(v=>typeof v==='string').slice(-1000),code:r.progress.code.filter(v=>MODES.some(m=>m.id===v))};return true}catch{storageAvailable=false;return false}}
function feedbackHTML(f=feedback){if(!f)return '';return `<div class="feedback ${f.ok?'':'error'}" role="status"><strong>${esc(f.title??(f.ok?'The answer is still alive.':'Pause. Test the reasoning.'))}</strong><p>${esc(f.text)}</p>${f.counterexample?`<details open><summary>Try a smaller counterexample</summary><span class="counterexample">cards = [${f.counterexample.a.map(v=>typeof v==='boolean'?(v?'T':'F'):v).join(', ')}]${mode(id).predicate?'':` · target = ${esc(f.counterexample.target)}`}<br>l = ${f.counterexample.l}, mid = ${f.counterexample.mid}, r = ${f.counterexample.r}<br>${esc(f.counterexample.reason)}</span><small class="counter-scope">${esc(f.counterexample.scope)}</small></details>`:''}</div>`}
function stateDescription(){const m=mode(id);return m.range==='closed'?`untested [${s.l}, ${s.r}]`:m.range==='open'?`untested [${s.l}, ${s.r})`:m.range==='cut'?`scan [${s.l}, ${s.r}) · answer [${s.l}, ${s.r}]`:`answer [${s.l}, ${s.r}]`}
function candidate(i){const m=mode(id);return i>=s.l&&(m.range==='open'?i<s.r:i<=s.r)}
function board(){const m=mode(id),mid=active(s)?midpoint(s):null;const indices=[...s.a.keys()];if(m.kind==='last'||s.l<0||s.r<0)indices.unshift(-1);if(m.range==='cut'||m.range==='open'||s.l===s.a.length)indices.push(s.a.length);const out=indices.map(i=>{const sentinel=i<0||i===s.a.length,live=candidate(i),markers=[i===s.l?'<span class="marker">l</span>':'',i===mid?'<span class="marker m">mid</span>':'',i===s.r?'<span class="marker">r</span>':''].join('');const value=sentinel?(i<0?'−1':'n'):typeof s.a[i]==='boolean'?(s.a[i]?'T':'F'):s.a[i];return `<div class="card-slot ${live?'live':'out'} ${sentinel?'sentinel':''} ${i===mid?'mid':''}" aria-label="${esc(sentinel?`sentinel ${i}`:`index ${i}, value ${s.a[i]}`)}, ${live?'possible':'ruled out'}${i===s.l?', left':''}${i===mid?', midpoint':''}${i===s.r?', right':''}"><div class="markers">${markers}</div><div class="card">${esc(value)}</div><div class="index">${sentinel?'sentinel':`i = ${i}`}</div></div>`}).join('');return `<div class="board-wrap" tabindex="0" role="region" aria-label="Search cards. Scroll horizontally for long arrays."><div class="cards ${indices.length<=5?'short':''}">${out}</div>${!s.a.length?'<div class="empty-board">No cards. The contract still defines an answer.</div>':''}</div><div class="legend"><span><i class="dot"></i>${m.range==='cut'?'Possible boundary':'Candidate'}</span><span><i class="dot mid"></i>Midpoint</span><span><i class="dot out"></i>Ruled out</span><span><i class="dot sentinel"></i>Not a card</span></div>`}
function comparison(){if(!active(s))return s.found!==null?`Match found at index ${s.found}.`:`${s.l} ${mode(id).guard} ${s.r} → false. The loop stops.`;const mid=midpoint(s),m=mode(id);if(m.predicate)return `mid = ${mid} · p[mid] = ${s.a[mid]?'True':'False'}`;const symbol=s.a[mid]<s.target?'&lt;':s.a[mid]>s.target?'&gt;':'==';return `mid = ${mid} · a[mid] = ${s.a[mid]} ${symbol} ${s.target}`}
function stage(){return !guard?1:completed?4:!active(s)?3:2}
function prompt(){
 if(!guard)return `<div class="challenge"><h3>When should this loop keep going?</h3><p class="muted" style="font-size:12px">Choose the guard for this interval contract. Then test it one move at a time.</p><div class="guard-options">${['l < r','l <= r','l > r'].map(c=>`<button data-action="guard" data-value="${esc(c)}"><code>${esc(c)}</code></button>`).join('')}</div>${feedbackHTML()}</div>`;
 if(completed)return `<span class="success-tag">Case explored · ${s.steps} comparison${s.steps===1?'':'s'}</span><h3 class="success-heading">The contract holds.</h3><p style="font-size:13px">${returnExplanation()}</p><div class="action-row"><button class="primary" data-action="next">Try the next case →</button><button class="secondary" data-action="tab" data-value="python">Build the Python</button></div>${feedbackHTML()}`;
 if(!active(s))return `<div class="challenge"><h3>What index should be returned?</h3><p class="muted" style="font-size:12px">${esc(mode(id).contract)}</p><form id="return-form" class="return-form"><label for="return-value">Return index<input id="return-value" name="return" type="number" step="1" min="-1" max="32" required inputmode="numeric" autocomplete="off"></label><button class="primary" type="submit">Check return</button></form>${feedbackHTML()}</div>`;
 if(pending)return `<div class="challenge">${feedbackHTML()}<button class="primary primary-wide" data-action="continue">${active(pending.state)?'Apply move & continue →':'Apply move & check return →'}</button><p class="toast">The board shows the comparison you just reasoned about. Continue to move the boundaries.</p></div>`;
 return `<div class="challenge"><h3>Which move keeps the answer alive?</h3><div class="moves">${MOVES.map((m,i)=>`<button class="move" data-action="move" data-value="${m.id}"><kbd>${i+1}</kbd><code>${esc(m.label)}</code><small>${esc(m.hint)}</small></button>`).join('')}</div>${feedbackHTML()}<div class="action-row"><button class="text-link" data-action="hint">Explain the next move</button>${history.length?'<button class="text-link" data-action="undo">Undo last move</button>':''}</div></div>`;
}
function returnExplanation(){const m=mode(id),answer=result(s);let text=`Return ${answer}. `;if(m.kind==='exact'||m.kind==='rotated')text+=s.found!==null?'Equality was checked, so mid is a matching index.':'The untested interval is empty, so no match exists. l may be an insertion position, but this contract asks for −1.';else if(m.kind==='last')text+='l and r have converged to the last qualifying position. Return r (l is equal). −1 means no element qualifies.';else if(id==='first_occ')text+='The lower bound needs a range and equality check. An insertion position by itself does not prove a match.';else if(id==='last_occ')text+='Look just before the upper bound and verify equality. Guard i ≥ 0; Python a[−1] would silently read the last card.';else text+='l and r meet at the first qualifying boundary. Both name the same position. n is a valid “no qualifying card” answer; never index a[n].';return esc(text)}
function invariantText(){const m=mode(id);if(m.kind==='last')return 'The last qualifying index stays in [l, r]. −1 is a real answer position, not an array element. All positions before l qualify; all after r fail.';if(m.kind==='first')return 'The first qualifying boundary stays in [l, r], including r. The cards still to inspect are [l, r). Everything before l fails; everything from r onward qualifies (when r < n).';return m.range==='closed'?'If a match exists, at least one matching card remains in [l, r]. Every move excludes a tested mid or returns it.':'If a match exists, at least one matching card remains in [l, r). r itself is already excluded.'}
function insight(){const m=mode(id);return `<aside class="insight" aria-label="Reasoning notebook"><div><div class="eyebrow" style="margin-bottom:12px">Your notebook</div><div class="metric"><span>left</span><strong>${s.l}</strong></div><div class="metric"><span>mid</span><strong>${active(s)?midpoint(s):'—'}</strong></div><div class="metric"><span>right</span><strong>${s.r}</strong></div><div class="metric"><span>comparisons</span><strong>${s.steps}</strong></div><p class="inline-code">${m.kind==='last'?'mid = l + (r − l + 1) // 2<br><span class="muted">Upper midpoint: important when l = mid.</span>':'mid = l + (r − l) // 2<br><span class="muted">Lower midpoint.</span>'}</p></div><div><div class="invariant"><strong>Promise to preserve</strong>${invariantText()}</div><p class="muted" style="font-size:11px;margin:12px 0 0">A smaller interval is only useful if it still contains the answer.</p></div><div class="insight-details"><details><summary>Why this contract works</summary><p>${esc(m.why)}</p><p><strong>Return contract:</strong><br>${esc(m.returnText)}</p></details></div></aside>`}
function blankSpec(){const m=mode(id);return [
 {key:'guard',label:'1. Continue while…',answer:m.guard,options:['l < r','l <= r','l > r']},
 {key:'mid',label:'2. Compute the midpoint',answer:m.kind==='last'?'l + (r - l + 1) // 2':'l + (r - l) // 2',options:['l + (r - l) // 2','l + (r - l + 1) // 2']},
 {key:'branch',label:m.kind==='first'?'3. A card qualifies when…':m.kind==='last'?'3. A card qualifies when…':'3. An exact match is when…',answer:m.predicate?'p[mid]':m.kind==='first'?`a[mid] ${['upper','last_occ'].includes(id)?'>':'>='} target`:m.kind==='last'?`a[mid] ${id==='last_le'?'<=':'<'} target`:'a[mid] == target',options:m.predicate?['p[mid]','not p[mid]']:['a[mid] >= target','a[mid] > target','a[mid] <= target','a[mid] < target','a[mid] == target']},
 {key:'move',label:m.kind==='first'?'4. When it qualifies…':m.kind==='last'?'4. When it qualifies…':'4. On equality…',answer:m.kind==='first'?'r = mid':m.kind==='last'?'l = mid':'return mid',options:['r = mid','r = mid - 1','l = mid','l = mid + 1','return mid']}
 ]}
function pythonPanel(){const m=mode(id);return `<div class="code-grid"><div><h3>Translate the promise into Python.</h3><p>Fill four choices, then compare the complete function with your moves. The guard, midpoint and retained boundary belong together.</p><form id="code-form">${blankSpec().map(b=>`<label class="blank-label" for="blank-${b.key}">${b.label}<select id="blank-${b.key}" name="${b.key}" required><option value="">Choose a line…</option>${b.options.map(v=>`<option value="${esc(v)}" ${blankValues[b.key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`).join('')}<button class="primary" id="check-code" type="submit">Check the translation</button></form>${feedbackHTML(codeFeedback)}<p style="margin-top:16px;font-size:11px">The function is tested against reference oracles. No Python runtime or account is loaded in your browser.</p></div><div><div class="eyebrow">Complete reference · ${m.tag}</div><pre class="code" aria-label="Python reference">${python(id).split('\n').map(line=>`<span class="code-line">${esc(line)}</span>`).join('')}</pre><button class="text-link" data-action="tab" data-value="trace">Inspect the executed steps →</button></div></div>`}
function reasonPanel(){return `<h3>Three questions. Every binary search.</h3><div class="code-grid"><div><p><strong>1 · What could the answer be?</strong><br>Name the return contract before choosing a loop. An exact match, an insertion boundary and a last qualifying index are different questions.</p><p><strong>2 · What does this comparison prove?</strong><br>Discard only positions that cannot contain the answer. “Equal” can mean stop, keep mid, or discard mid — it depends on the contract.</p></div><div><p><strong>3 · Will this always get smaller?</strong><br>Preserving the answer is not enough. Try one and two positions. If <code>l = mid</code> with the lower midpoint leaves l unchanged, use the upper midpoint for this contract.</p><p><strong>Then read the return value.</strong><br>At the stop state, explain what l and r mean. Sometimes they are equal. Sometimes they cross. Sometimes you return an earlier saved match.</p></div></div>`}
function tracePanel(){return `<h3>Your search, one Python step at a time.</h3><p>Each move in the game executes one loop iteration. The trace records the state before that move; no automatic playback or time limit.</p>${history.length?`<ol class="trace-list">${history.map(h=>`<li><code>l=${h.before.l}, mid=${midpoint(h.before)}, r=${h.before.r}</code> → <code>${esc(MOVES.find(m=>m.id===h.move).label)}</code><br>${esc(h.explanation)}</li>`).join('')}</ol>`:'<p>No moves yet. Choose the guard, then make a move above.</p>'}<div class="compare">Current: ${esc(stateDescription())}${!active(s)?`<br>Stopped · ${esc(mode(id).returnText)}`:''}</div>${history.length&&!pending?'<button class="secondary small" data-action="undo">Undo one step</button>':''}<button class="text-link" style="margin-left:12px" data-action="tab" data-value="python">View Python translation</button>`}
function contractsPanel(){return `<h3>Same array. Different questions.</h3><p>For <code>[1, 3, 3, 7]</code> and target <code>3</code>, compare the answers. These return expressions belong to the displayed implementation, not to every binary search.</p><div class="table-scroll"><table class="comparison-table"><thead><tr><th>Question</th><th>Answer</th><th>Stop / return</th></tr></thead><tbody><tr><td>Any exact match</td><td>1 or 2</td><td>Return mid on equality; otherwise −1</td></tr><tr><td>First ≥ (lower bound)</td><td>1</td><td>l = r; return l</td></tr><tr><td>First > (upper bound)</td><td>3</td><td>l = r; return l</td></tr><tr><td>Last ≤</td><td>2</td><td>l = r; return r</td></tr><tr><td>Last <</td><td>0</td><td>l = r; return r</td></tr><tr><td>First / last occurrence</td><td>1 / 2</td><td>Check equality at lower / upper−1</td></tr></tbody></table></div><p style="margin-top:15px">If target is 9, both insertion bounds return n = 4, but exact and occurrence searches return −1. If target is 0, both last-qualifying searches return −1.</p><h3 style="margin-top:22px">Why someone else might return right</h3><p>A different valid template keeps an untested inclusive interval and moves <code>l = mid + 1</code> when <code>a[mid] ≤ target</code>, otherwise <code>r = mid − 1</code>. When l crosses r, r is the last ≤ index and l is the first > position. Our retained-answer template instead stops at l = r. The invariant determines the return expression.</p>`}
function caveatPanel(){return `<h3>Duplicates are fine — until the proof changes.</h3><p>Sorted repeated values work in exact search, lower/upper bounds and first/last occurrence. The rotated lesson deliberately requires distinct values.</p><div class="compare">[1, 0, 1, 1, 1] · target 0<br>a[l] == a[mid] == a[r] == 1</div><p>Equal endpoint and midpoint values hide which half contains the pivot. Treating the left half as strictly sorted can discard the 0. A duplicates-aware search can shrink an ambiguous edge one position at a time, while preserving a possible match.</p><p><strong>The tradeoff:</strong> with distinct values, each iteration removes roughly half the candidates: O(log n) comparisons. With repeated values in a rotated array, ambiguous shrinking can require O(n) in the worst case. The distinct-values rule cannot be reused unchanged.</p><h3>Monotone means one direction of change.</h3><p>First true assumes false…true; last true assumes true…false. A pattern like <code>F, T, F</code> breaks the proof. Custom cases reject non-monotone inputs instead of teaching a misleading result.</p><p>For a costly predicate, the number of predicate evaluations and the cost of each evaluation are separate. These lessons illustrate O(log n) evaluations with O(1) state.</p>`}
function customHTML(){if(!custom)return '';return `<section class="custom"><form id="custom-form"><label for="custom-array">${mode(id).predicate?'Cards · T/F, comma separated':'Cards · whole numbers, comma separated'}<input id="custom-array" name="array" placeholder="${mode(id).predicate?'F, F, T, T':'1, 3, 3, 7'}" value="${esc(s.a.map(v=>typeof v==='boolean'?(v?'T':'F'):v).join(', '))}"></label>${mode(id).predicate?'':`<label class="target-input" for="custom-target">Target<input id="custom-target" name="target" type="number" step="1" required value="${s.target}"></label>`}<button class="primary" id="play-custom" type="submit">Play this case</button><button type="button" data-action="custom">Cancel</button></form><p>Leave cards blank for an empty array. Up to 32 cards; long rows scroll horizontally. ${mode(id).predicate?'Use the lesson’s monotone order.':id==='rotated'?'Use one rotation of distinct sorted values.':'Keep values sorted; repeats are welcome.'}</p><div id="custom-error" role="alert"></div></section>`}
function render(){const focused=document.activeElement;const focusSelector=focused?.id?'#'+CSS.escape(focused.id):focused?.dataset?.action?'[data-action="'+focused.dataset.action+'"]'+(focused.dataset.value?'[data-value="'+CSS.escape(focused.dataset.value)+'"]':''):null;const m=mode(id),st=stage(),doneForMode=progress.completed.filter(k=>k.startsWith(id+':')).length;let lastGroup='';$('#app').innerHTML=`
 <header class="topbar"><a class="brand" href="#" data-action="home"><img src="icon.svg" alt="">bisect<span style="color:var(--orange)">.</span><small>A binary search field guide</small></a><div class="top-tools"><span class="privacy">Local progress · saved here</span><button class="text-button" data-action="reset">Reset progress</button></div></header>
 <div class="app-layout"><aside class="sidebar ${menu?'expanded':''}"><button class="mobile-menu" data-action="menu" aria-expanded="${menu}"><span>Learning path · ${String(MODES.findIndex(x=>x.id===id)+1).padStart(2,'0')} / ${MODES.length}</span><span>${menu?'Close −':'Explore +'}</span></button><div class="sidebar-title"><span class="eyebrow">Learning path</span><span class="eyebrow">11</span></div><nav aria-label="Learning path">${MODES.map((lesson,i)=>{const heading=lesson.group!==lastGroup?`<div class="lesson-group">${lesson.group}</div>`:'';lastGroup=lesson.group;return heading+`<button class="lesson ${id===lesson.id?'active':''}" data-action="lesson" data-value="${lesson.id}" ${id===lesson.id?'aria-current="step"':''}><span class="lesson-num">${String(i+1).padStart(2,'0')}</span><span>${lesson.name}</span>${progress.completed.some(k=>k.startsWith(lesson.id+':'))?'<span class="lesson-check" aria-label="Case explored">✓</span>':''}</button>`}).join('')}</nav><div class="sidebar-foot"><span class="no-pressure">No timer. Room to think.</span><p style="margin:12px 0 0">${progress.completed.length} case${progress.completed.length===1?'':'s'} explored.<br>Progress records practice, not mastery.</p></div></aside>
 <main class="main" id="main">${resetOpen?'<div class="reset-box" role="alert"><strong>Reset this browser’s Bisect progress?</strong><p style="margin:8px 0">This clears explored cases and the current search. Other apps and browser data stay untouched.</p><div class="action-row"><button data-action="confirm-reset">Reset Bisect</button><button class="primary" data-action="cancel-reset">Keep progress</button></div></div>':''}<div class="hero"><div class="hero-copy"><p class="eyebrow">Think in possibilities, not rules</p><h1>Keep the answer alive<span style="color:var(--orange)">.</span></h1><p>Choose what to discard. Watch what survives.<br>Understand the boundaries before memorising the code.</p></div><div class="hero-mark" aria-hidden="true">[<span>•</span>]</div></div>
 <section class="workspace" aria-label="Interactive search"><div class="workspace-head"><div><span class="eyebrow">Lesson ${String(MODES.findIndex(x=>x.id===id)+1).padStart(2,'0')} <span style="color:#9da79a">/ ${doneForMode} cases explored</span></span><h2 class="lesson-title">${m.name}</h2><span class="pill">${esc(m.tag)}</span></div><div class="case-tools"><label class="hidden" for="case-select">Choose an example</label><select id="case-select" aria-label="Choose an example">${generateCases(id).map((c,i)=>`<option value="${i}" ${caseIndex===i?'selected':''}>${i+1}. ${c.name}</option>`).join('')}${caseName==='Custom case'?'<option value="custom" selected>Custom case</option>':''}</select><button class="small" data-action="custom" aria-expanded="${custom}">Custom</button><button class="small" data-action="restart" aria-label="Restart this case">↺</button></div></div>${customHTML()}<div class="steps">${['Contract','Guard','Keep / discard','Return','Translate'].map((t,i)=>`<span class="step ${i===st?'current':i<st?'past':''}"><b>${i<st?'✓':i+1}</b>${t}</span>`).join('')}</div><div class="play-grid"><div class="play-main"><div class="contract"><span class="eyebrow">The promise</span>${esc(m.contract)}</div><div class="target-row"><div class="target">${m.predicate?'<span>Predicate</span><strong style="font-size:18px">'+(id==='first_true'?'F → T':'T → F')+'</strong>':'<span>Find</span><strong>'+s.target+'</strong>'}<span class="muted">· n = ${s.a.length}</span></div><span class="state-label">${esc(stateDescription())}</span></div>${board()}<div class="compare" aria-live="polite">${comparison()}</div>${prompt()}</div>${insight()}</div></section>
 <section class="below" aria-label="Explore the reasoning"><div class="tabs" role="group" aria-label="Reference panels">${[['reason','The reasoning'],['python','Python workshop'],['trace','Step trace'],['contracts','Return contracts'],['caveat','Duplicates & limits']].map(([v,label])=>`<button class="tab ${tab===v?'active':''}" id="tab-${v}" aria-pressed="${tab===v}" aria-controls="reference-panel" data-action="tab" data-value="${v}">${label}</button>`).join('')}</div><div class="panel" id="reference-panel" role="region" aria-labelledby="tab-${tab}">${tab==='python'?pythonPanel():tab==='trace'?tracePanel():tab==='contracts'?contractsPanel():tab==='caveat'?caveatPanel():reasonPanel()}</div></section><footer class="footer"><span>Made for understanding. Practice examples are illustrative.</span><span>${storageAvailable?'Saved on this browser only.':'Browser storage unavailable; progress lasts for this session.'} · v1.0</span></footer></main></div>`;requestAnimationFrame(()=>{const board=document.querySelector('.board-wrap'),card=document.querySelector('.card-slot.mid')??document.querySelector('.card-slot.live');if(board&&card){const b=board.getBoundingClientRect(),c=card.getBoundingClientRect();board.scrollLeft+=c.left-b.left-board.clientWidth/2+c.width/2}});if(focusSelector)requestAnimationFrame(()=>{let el=document.querySelector(focusSelector);if(!el||!el.getClientRects().length)el=document.querySelector('[data-action="guard"], [data-action="move"], #return-value, [data-action="next"]');el?.focus({preventScroll:true})});}

function focusAction(action){requestAnimationFrame(()=>document.querySelector(`[data-action="${action}"]`)?.focus({preventScroll:true}))}
function chooseGuard(c){const f=guardFeedback(id,c);feedback={ok:f.ok,text:f.text,title:f.ok?'The guard matches the interval.':undefined};if(f.ok){guard=true;save()}render();if(f.ok)active(s)?focusAction('move'):$('#return-value')?.focus({preventScroll:true})}
function chooseMove(move){if(!guard||completed||pending||!active(s))return;const a=applyMove(s,move);feedback={ok:a.ok,text:a.reason,counterexample:a.counterexample};if(a.ok)pending={...a,move,before:s};render();if(a.ok)focusAction('continue')}
function undo(){if(!history.length)return;const last=history.pop();s=last.before;completed=false;pending=null;feedback={ok:true,title:'One step back.',text:'The earlier state is restored. Try the comparison again.'};save();render()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,v=b.dataset.value;if(a==='home'){e.preventDefault();start('exact_closed');window.scrollTo({top:0,behavior:'smooth'})}else if(a==='lesson'){menu=false;start(v);window.scrollTo({top:0,behavior:'smooth'})}else if(a==='guard')chooseGuard(v);else if(a==='move')chooseMove(v);else if(a==='continue'){if(!pending)return;history.push({before:pending.before,move:pending.move,explanation:pending.reason});s=pending.state;pending=null;feedback=null;save();render();active(s)?focusAction('move'):$('#return-value')?.focus({preventScroll:true})}else if(a==='hint'){feedback={ok:true,title:'A proof to try',text:mode(id).why+' Consider '+MOVES.find(x=>x.id===expectedMove(s)).label+'. Make the move yourself to continue.'};render()}else if(a==='undo')undo();else if(a==='next'){start(id,(caseIndex+1)%generateCases(id).length)}else if(a==='restart'){start(id,caseIndex,{name:caseName,a:s.a,target:s.target})}else if(a==='tab'){tab=v;render();document.querySelector('#tab-'+v)?.focus({preventScroll:true})}else if(a==='custom'){custom=!custom;render();if(custom)$('#custom-array')?.focus({preventScroll:true})}else if(a==='menu'){menu=!menu;render()}else if(a==='reset'){resetOpen=true;render();focusAction('cancel-reset')}else if(a==='cancel-reset'){resetOpen=false;render()}else if(a==='confirm-reset'){progress={completed:[],code:[]};resetOpen=false;tab='reason';start('exact_closed');feedback={ok:true,title:'A fresh start.',text:'Only Bisect’s local progress has been cleared.'};render()}});
document.addEventListener('change',e=>{if(e.target.id==='case-select'&&e.target.value!=='custom')start(id,Number(e.target.value));if(e.target.closest('#code-form'))blankValues[e.target.name]=e.target.value});
document.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);if(e.target.id==='return-form'){const answer=Number(data.get('return'));const exact=['exact','rotated'].includes(mode(id).kind);const valid=exact&&result(s)!==-1?Number.isInteger(answer)&&answer>=0&&answer<s.a.length&&s.a[answer]===s.target:answer===result(s);if(valid){completed=true;const key=caseKey();if(!progress.completed.includes(key))progress.completed.push(key);progress.completed=progress.completed.slice(-1000);feedback={ok:true,title:'You read the stop state correctly.',text:answer!==result(s)?'That index satisfies the any-match contract. This particular execution returned index '+result(s)+'.':'Try an edge case next. A result on one example is a starting point for a proof.'};save();render();focusAction('next')}else{feedback={ok:false,title:'Read the contract again.',text:`Your answer ${answer} does not satisfy this case. ${mode(id).kind==='exact'||mode(id).kind==='rotated'?'A crossed interval means absent, so return −1 unless equality already found a match.':mode(id).kind==='last'?'The converged right boundary is the last qualifying index; −1 means none.':id==='first_occ'||id==='last_occ'?'The boundary needs a range and equality check; an absent target returns −1.':'The converged boundary is the answer, including n when no card qualifies.'}`};render();$('#return-value')?.focus({preventScroll:true})}}else if(e.target.id==='custom-form'){const input=String(data.get('array')).trim().replace(/^\[/,'').replace(/\]$/,'');const tokens=input?input.split(/[\s,]+/).filter(Boolean):[];const a=mode(id).predicate?tokens.map(v=>/^t(rue)?$/i.test(v)?true:/^f(alse)?$/i.test(v)?false:NaN):tokens.map(v=>/^-?\d+$/.test(v)?Number(v):NaN);const target=mode(id).predicate?0:Number(data.get('target'));const error=validateInput(id,a,target);if(error){$('#custom-error').innerHTML=`<div class="feedback error">${esc(error)}</div>`;return}start(id,0,{name:'Custom case',a,target})}else if(e.target.id==='code-form'){const wrong=blankSpec().filter(b=>data.get(b.key)!==b.answer);for(const b of blankSpec())blankValues[b.key]=data.get(b.key);codeFeedback=wrong.length?{ok:false,title:'One contract, four connected choices.',text:wrong.map(b=>`${b.label.replace(/^\d\. /,'')}: try ${b.answer}.`).join(' ')+' '+mode(id).why}:{ok:true,title:'The translation is consistent.',text:'The complete function shows the return checks too. Compare it with a one-card and a missing-target case.'};if(!wrong.length&&!progress.code.includes(id))progress.code.push(id);save();render()}});
document.addEventListener('keydown',e=>{if(e.repeat||e.altKey||e.metaKey||e.ctrlKey||e.target.matches('input,select,textarea'))return;if(/^[1-5]$/.test(e.key)&&guard&&active(s)&&!pending){e.preventDefault();chooseMove(MOVES[Number(e.key)-1].id)}if(e.key==='Escape'&&(custom||resetOpen||menu)){custom=false;resetOpen=false;menu=false;render()}});
if(restore())render();else start();
